_visualize_alongside_descriptors_guardrail = Guardrail(
    get_prompt("guardrails", "fields_with_descriptors"),
    "field_visualized_alongside_descriptors",
    "Set to True if this field is visualized alongside with anything derived from it that the user wants to visualize.",
